async function testCheckEndpoint() {
  try {
    // Test basic rule evaluation
    const response = await request
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      });

    console.log('Response status:', response.status);
    console.log('Response body:', response.body);

