const app = require('./app');
const supertest = require('supertest');

const request = supertest(app);

async function testCheckEndpoint() {
  try {
    // Test case 1: Simple boolean expression
    const response1 = await request
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      });

    console.log('Test 1 - Expected: true, Actual:', response1.body.result);

    // Test case 2: False condition
    const response2 = await request
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 50 }
      });

    console.log('Test 2 - Expected: false, Actual:', response2.body.result);

    // Test case 3: String comparison
    const response3 = await request
      .post('/check')
      .send({
        rule: 'ctx.status === "active"',
        context: { status: "active" }
      });

    console.log('Test 3 - Expected: true, Actual:', response3.body.result);

    console.log('All tests completed successfully!');
  } catch (error) {
    console.error('Test failed:', error.message);
  }
}

// Run the tests
testCheckEndpoint();

