const app = require('./app');
const http = require('http');

// Create a test server
const server = http.createServer(app);

// Start server on a different port for testing
server.listen(3001, async () => {
  console.log('Test server running on port 3001');

  // Simple test using built-in http module
  const options = {
    hostname: 'localhost',
    port: 3001,
    path: '/check',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    }
  };

  const testRequests = [
    {
      rule: 'ctx.amount > 100',
      context: { amount: 150 }
    },
    {
      rule: 'ctx.amount > 100',
      context: { amount: 50 }
    },
    {
      rule: 'ctx.status === "active"',
      context: { status: "active" }
    }
  ];

  for (let i = 0; i < testRequests.length; i++) {
    const testData = testRequests[i];

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        console.log(`Test ${i+1}:`, JSON.parse(data));
      });
    });

    req.on('error', (error) => {
      console.error(`Test ${i+1} error:`, error.message);
    });

    req.write(JSON.stringify(testData));
    req.end();
  }

  // Close server after tests
  setTimeout(() => {
    server.close();
    console.log('Tests completed');
  }, 1000);
});

